{"content":"package parser

import (
	"testing"
)

func TestParsePair(t *testing.T) {
	tests := []struct {
		name     string
		input    string
		expectedKey   string
		expectedValue string
		expectedOK     bool
	}{
		{
			name:     "valid pair",
			input:    "key=value",
			expectedKey: "key",
			expectedValue: "value",
			expectedOK: true,
		},
		{
			name:     "empty input",
			input:    "",
			expectedKey: "",
			expectedValue: "",
			expectedOK: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			k, v, ok := ParsePair(tt.input)
			if k != tt.expectedKey {
				t.Errorf("ParsePair(%q).key = %q; want %q", tt.input, k, tt.expectedKey)
			}
			if v != tt.expectedValue {
				t.Errorf("ParsePair(%q).value = %q; want %q", tt.input, v, tt.expectedValue)
			}
			if ok != tt.expectedOK {
				t.Errorf("ParsePair(%q).ok = %v; want %v", tt.input, ok, tt.expectedOK)
			}
		})
	}
}
","override":"true","path":"parser/parser_test.go"}

